import{_ as a,o as r,c as o,a6 as i}from"./chunks/framework.QBF2cGGQ.js";const m=JSON.parse('{"title":"08 · 可观测与运维","description":"","frontmatter":{},"headers":[],"relativePath":"guide/08-observability.md","filePath":"guide/08-observability.md","lastUpdated":1793327470000}'),t={name:"guide/08-observability.md"};function n(p,s,l,e,c,g){return r(),o("div",null,[...s[0]||(s[0]=[i('<h1 id="_08-·-可观测与运维" tabindex="-1">08 · 可观测与运维 <a class="header-anchor" href="#_08-·-可观测与运维" aria-label="Permalink to &quot;08 · 可观测与运维&quot;">​</a></h1><blockquote><p><strong>投入权重：5%</strong> · 出事的时候，能不能在 5 分钟内定位到&quot;是检索错了还是模型抽风&quot;，全靠这一层。</p></blockquote><h2 id="为什么它比看起来重要" tabindex="-1">为什么它比看起来重要 <a class="header-anchor" href="#为什么它比看起来重要" aria-label="Permalink to &quot;为什么它比看起来重要&quot;">​</a></h2><p>AI 系统的故障特别隐蔽：接口 200、响应正常、内容全错。传统监控（QPS、错误率、CPU）完全抓不到。用户投诉&quot;它今天答得不对&quot;，而你打开日志只看到一堆 200。</p><p>可观测性就是让&quot;答得不对&quot;这件事变得可查。它的核心是 trace——把一次请求的每一步（prompt 组装、检索、模型调用、工具调用）都记录下来，能完整回放。</p><h2 id="trace" tabindex="-1">Trace <a class="header-anchor" href="#trace" aria-label="Permalink to &quot;Trace&quot;">​</a></h2><ul><li><strong>Trace 的概念</strong> <span class="prio prio-must">必须</span> — 一次请求的完整链路：prompt 组装 → 检索 → 模型调用 → 工具调用 → 输出。每步都要留痕。</li><li><strong>OpenTelemetry GenAI 语义约定</strong> <span class="prio prio-imp">重要</span> — 行业标准字段命名，接哪家平台都通用。</li><li><strong>Langfuse</strong> <span class="prio prio-must">必须</span> — 开源自部署首选，trace + 评测 + 成本一体。</li><li><strong>LangSmith</strong> <span class="prio prio-imp">重要</span> — LangChain 官方，体验好但绑定生态。</li><li><strong>Arize Phoenix / Helicone</strong> <span class="prio prio-imp">重要</span> — 开源可观测方案，按需选。</li><li><strong>会话回放</strong> <span class="prio prio-must">必须</span> — 能完整重放用户那次对话，包括检索到的原文。排查问题的必备能力。</li></ul><h2 id="日志与成本" tabindex="-1">日志与成本 <a class="header-anchor" href="#日志与成本" aria-label="Permalink to &quot;日志与成本&quot;">​</a></h2><ul><li><strong>全量 prompt/response 记录</strong> <span class="prio prio-must">必须</span> — 必须存，但要脱敏。这是后续做数据集和归因的原料。</li><li><strong>PII 脱敏</strong> <span class="prio prio-must">必须</span> — 手机号、身份证、邮箱入库前脱敏。合规硬要求。</li><li><strong>token 统计与成本分摊</strong> <span class="prio prio-must">必须</span> — 按用户/租户/功能维度统计，才能知道谁在烧钱。</li><li><strong>延迟分解</strong> <span class="prio prio-must">必须</span> — 排队/检索/首 token/生成 各占多少，优化才知道往哪打。</li><li><strong>错误分类</strong> <span class="prio prio-must">必须</span> — 超时/限流/内容审核/格式错误/工具失败。分类后才能定告警。</li><li><strong>采样策略</strong> <span class="prio prio-imp">重要</span> — 全量存成本高，可采样，但错误与差评必须 100% 留存。</li></ul><h2 id="版本与发布" tabindex="-1">版本与发布 <a class="header-anchor" href="#版本与发布" aria-label="Permalink to &quot;版本与发布&quot;">​</a></h2><ul><li><strong>三类版本管理</strong> <span class="prio prio-must">必须</span> — prompt 版本 / 模型版本 / 索引版本。三者任一变更都要能回滚。</li><li><strong>灰度发布</strong> <span class="prio prio-must">必须</span> — 按用户比例放量，观察指标再全量。</li><li><strong>回滚策略</strong> <span class="prio prio-must">必须</span> — 配置化切换，不依赖重新部署。</li><li><strong>告警设计</strong> <span class="prio prio-imp">重要</span> — 错误率、P95 延迟、成本突增、审核拦截率异常。</li><li><strong>变更记录</strong> <span class="prio prio-imp">重要</span> — 每次上线记下&quot;改了什么&quot;，否则指标波动时无法归因。</li></ul><h2 id="反馈闭环" tabindex="-1">反馈闭环 <a class="header-anchor" href="#反馈闭环" aria-label="Permalink to &quot;反馈闭环&quot;">​</a></h2><ul><li><strong>显式反馈</strong> <span class="prio prio-must">必须</span> — 点赞/点踩/评分。设计要轻，别打断流程。</li><li><strong>隐式反馈</strong> <span class="prio prio-must">必须</span> — 复制、采纳、编辑后发送、重新生成、中途打断。比显式更真实。</li><li><strong>badcase 归因流程</strong> <span class="prio prio-must">必须</span> — 收集 → 分类（检索/生成/理解/格式）→ 修 → 回归测试。要有固定节奏。</li><li><strong>数据飞轮</strong> <span class="prio prio-imp">重要</span> — 用户反馈 → 评测集 → 优化 → 更好体验 → 更多使用。这是长期壁垒。</li><li><strong>归因的责任人</strong> <span class="prio prio-imp">重要</span> — 没有人负责的 badcase 池会迅速腐烂。要指定轮值。</li></ul>',13)])])}const d=a(t,[["render",n]]);export{m as __pageData,d as default};
